"""Find when a cron schedule next fires.

An expression has five whitespace-separated fields: minute (0-59), hour
(0-23), day of month (1-31), month (1-12), and day of week (0-7, where both
0 and 7 are Sunday). Each field is a comma-separated list of items, where
an item is:

- ``*``, every value in the field's range,
- a value ``N``,
- a range ``A-B`` (inclusive, with ``A <= B``),
- any of those followed by ``/S`` for every ``S``-th value starting at the
  first one (``*/15`` in the minute field is 0, 15, 30, 45; ``10-30/10`` is
  10, 20, 30; ``5/20`` is 5, 25, 45, i.e. from 5 to the end of the range).

Months may also be given by the names ``JAN``-``DEC`` and days of the week
by ``SUN``-``SAT``, in any case, including in ranges. A value outside its
field's range, a malformed item, or a field count other than five raises
``ValueError``.

As in Vixie cron, when both the day-of-month and day-of-week fields are
restricted (neither is exactly ``*``), a day matches if it matches either
one; otherwise it must match both.

Times are naive datetimes. ``next_run`` returns the earliest matching time
strictly after ``after``, with seconds and microseconds zero. If nothing
matches within the next five years (e.g. ``0 0 30 2 *``), it raises
``ValueError``.
"""

from __future__ import annotations

import calendar
from datetime import datetime, timedelta
from typing import Dict, FrozenSet, List, Optional, Sequence, Set, Tuple

_MONTH_NAMES: Dict[str, int] = {
    "JAN": 1,
    "FEB": 2,
    "MAR": 3,
    "APR": 4,
    "MAY": 5,
    "JUN": 6,
    "JUL": 7,
    "AUG": 8,
    "SEP": 9,
    "OCT": 10,
    "NOV": 11,
    "DEC": 12,
}

_WEEKDAY_NAMES: Dict[str, int] = {
    "SUN": 0,
    "MON": 1,
    "TUE": 2,
    "WED": 3,
    "THU": 4,
    "FRI": 5,
    "SAT": 6,
}

_ONE_MINUTE = timedelta(minutes=1)


def next_run(expression: str, after: datetime) -> datetime:
    """The first time after ``after`` that ``expression`` fires."""
    fields = expression.split()
    if len(fields) != 5:
        raise ValueError(
            "cron expression must have exactly five fields, got %d" % len(fields)
        )
    minute_text, hour_text, dom_text, month_text, dow_text = fields

    minutes = _parse_field(minute_text, 0, 59)
    hours = _parse_field(hour_text, 0, 23)
    days = _parse_field(dom_text, 1, 31)
    months = _parse_field(month_text, 1, 12, _MONTH_NAMES)
    # 7 is another spelling of Sunday, so fold it onto 0.
    weekdays = frozenset(
        value % 7 for value in _parse_field(dow_text, 0, 7, _WEEKDAY_NAMES)
    )

    # The Vixie rule keys off the raw field text: ``*/2`` is restricted too.
    either_day = dom_text != "*" and dow_text != "*"

    try:
        start = after.replace(second=0, microsecond=0) + _ONE_MINUTE
    except OverflowError:
        raise ValueError("no time after %s" % (after,)) from None

    limit = _add_years(after, 5)
    hour_values = sorted(hours)
    minute_values = sorted(minutes)
    month_values = sorted(months)

    for year in range(start.year, limit.year + 1):
        for month in month_values:
            if year == start.year and month < start.month:
                continue
            if year == limit.year and month > limit.month:
                continue

            first_day = 1
            if year == start.year and month == start.month:
                first_day = start.day
            last_day = calendar.monthrange(year, month)[1]
            if year == limit.year and month == limit.month:
                last_day = min(last_day, limit.day)

            for day in range(first_day, last_day + 1):
                if not _day_matches(year, month, day, days, weekdays, either_day):
                    continue

                if (year, month, day) == (start.year, start.month, start.day):
                    candidate = _time_on_date_from(
                        year, month, day, hour_values, minute_values, start
                    )
                    if candidate is None:
                        continue
                else:
                    candidate = datetime(
                        year, month, day, hour_values[0], minute_values[0]
                    )

                if candidate > limit:
                    raise ValueError(
                        "no match for %r within five years of %s"
                        % (expression, after)
                    )
                return candidate

    raise ValueError(
        "no match for %r within five years of %s" % (expression, after)
    )


def _parse_field(
    text: str,
    low: int,
    high: int,
    names: Optional[Dict[str, int]] = None,
) -> FrozenSet[int]:
    """Parse one comma-separated cron field into the set of its values."""
    values: Set[int] = set()
    items = text.split(",")
    for item in items:
        if not item:
            raise ValueError("empty item in cron field %r" % (text,))
        values.update(_parse_item(item, low, high, names))
    return frozenset(values)


def _parse_item(
    item: str,
    low: int,
    high: int,
    names: Optional[Dict[str, int]],
) -> Sequence[int]:
    """Parse a single item, which may carry a ``/S`` step."""
    base, step = _split_step(item)

    if base == "*":
        start, end = low, high
    elif "-" in base:
        bounds = base.split("-")
        if len(bounds) != 2:
            raise ValueError("malformed range %r" % (item,))
        start, start_is_name = _parse_value(bounds[0], low, high, names)
        end, end_is_name = _parse_value(bounds[1], low, high, names)
        if names is not None and start_is_name != end_is_name:
            raise ValueError("cannot mix a name and a number in %r" % (item,))
        if start > end:
            raise ValueError("range %r is backwards" % (item,))
    else:
        start, _ = _parse_value(base, low, high, names)
        if step is None:
            return (start,)
        end = high

    if step is None:
        step = 1

    return range(start, end + 1, step)


def _split_step(item: str) -> Tuple[str, Optional[int]]:
    """Split ``base/S`` into its base and a validated positive step."""
    parts = item.split("/")
    if len(parts) == 1:
        return item, None
    if len(parts) != 2:
        raise ValueError("malformed step in %r" % (item,))
    base, step_text = parts
    if not step_text.isascii() or not step_text.isdigit():
        raise ValueError("invalid step %r in %r" % (step_text, item))
    step = int(step_text)
    if step <= 0:
        raise ValueError("step must be positive in %r" % (item,))
    return base, step


def _parse_value(
    text: str,
    low: int,
    high: int,
    names: Optional[Dict[str, int]],
) -> Tuple[int, bool]:
    """Parse a number or a name, returning the value and whether it was a name."""
    if not text:
        raise ValueError("empty value in cron expression")
    if names is not None:
        name = names.get(text.upper())
        if name is not None:
            return name, True
    if not text.isascii() or not text.isdigit():
        raise ValueError("invalid value %r" % (text,))
    value = int(text)
    if value < low or value > high:
        raise ValueError(
            "value %d is outside the range %d-%d" % (value, low, high)
        )
    return value, False


def _day_matches(
    year: int,
    month: int,
    day: int,
    days: FrozenSet[int],
    weekdays: FrozenSet[int],
    either_day: bool,
) -> bool:
    """Whether a calendar day satisfies the day-of-month/day-of-week rule."""
    day_match = day in days
    # calendar.weekday() is Monday=0; cron is Sunday=0.
    weekday = (calendar.weekday(year, month, day) + 1) % 7
    weekday_match = weekday in weekdays
    if either_day:
        return day_match or weekday_match
    return day_match and weekday_match


def _time_on_date_from(
    year: int,
    month: int,
    day: int,
    hours: List[int],
    minutes: List[int],
    start: datetime,
) -> Optional[datetime]:
    """First matching time on ``start``'s date at or after ``start``."""
    for hour in hours:
        if hour < start.hour:
            continue
        for minute in minutes:
            if hour == start.hour and minute < start.minute:
                continue
            return datetime(year, month, day, hour, minute)
    return None


def _add_years(moment: datetime, years: int) -> datetime:
    """``moment`` shifted by whole years, clamped to the end of the calendar."""
    year = moment.year + years
    if year > datetime.max.year:
        return datetime.max
    day = min(moment.day, calendar.monthrange(year, moment.month)[1])
    return moment.replace(year=year, day=day)
